head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05909.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.isFirstLoad = false;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_checkMktactEnforceDd = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=LIST_CHGLIST_MKTACTENFORCEDD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.chglist.mktactenforcedd.select.condition" + "&{P}param01=" + scwin.Isur_cd;
    dts_CheckDate.DataID = encodeURI(url);
    dts_CheckDate.reset();
};
scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_MST + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
        url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_ISU_NM_CHG + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Isu.DataID = encodeURI(url);
        dts_Isu.reset();
    }
};
scwin.fn_new_onload = function() {
    var url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_MST + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ISUR_CD=" + scwin.Isur_cd;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
    var url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_ISU_NM_CHG + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&ISUR_CD=" + scwin.Isur_cd + "&GUBUN_CD=" + scwin.gubun;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_checkGubun = function() {
    if (scwin.gubun == '1') {
        // 발행사
        txb_AfchgElwIsurNm.setReadOnly(false);
        txb_AfchgElwIsurEngNm.setReadOnly(false);
        txb_AfchgUlyNm.setReadOnly(true);
        txb_AfchgUlyEngNm.setReadOnly(true);
        txb_AfchgUlyNm.setStyle("backgroundcolor", "#b9d4f7");
        txb_AfchgUlyEngNm.setStyle("backgroundcolor", "#b9d4f7");
    } else if (scwin.gubun == '2') {
        //기초자산
        txb_AfchgElwIsurNm.setReadOnly(true);
        txb_AfchgElwIsurEngNm.setReadOnly(true);
        txb_AfchgUlyNm.setReadOnly(false);
        txb_AfchgUlyEngNm.setReadOnly(false);
        txb_AfchgElwIsurNm.setStyle("backgroundcolor", "#b9d4f7");
        txb_AfchgElwIsurEngNm.setStyle("backgroundcolor", "#b9d4f7");
    }
};
scwin.fn_changeIsuNmByBatch = function() {
    if (!scwin.fn_CheckForm()) return false;
    grd_isu.redraw = false;
    if (scwin.gubun == '1') {
        for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV1", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ELW_ISUR_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV1", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ELW_ISUR_ENG_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_NM", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_NM", dts_Isu.NameString(i, "AFCHG_ISU_NM") = );*/ X = X);
            dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV2") + "호";
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_NM", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_ENG_NM", dts_Isu.NameString(i, "AFCHG_ISU_ENG_NM") = );*/ X = X);
            dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV2");
        }

    } else if (scwin.gubun == '2') {
        for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
            dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV3", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ULY_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV3", dts_Mst.getCellData(dts_Mst.getRowPosition(), "AFCHG_ULY_ENG_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_NM", dts_Isu.getCellData(i, "BFCHG_ISU_NM"));
            dts_Isu.setCellData(i, "AFCHG_ISU_ENG_NM", dts_Isu.getCellData(i, "BFCHG_ISU_ENG_NM"));
        }

    }
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        dts_Isu.setCellData(i, "AFCHG_ISU_ABBRV", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_ABBRV", dts_Isu.NameString(i, "AFCHG_ISU_ABBRV") = );*/ X = X);
        dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV3") + dts_Isu.getCellData(i, "AFCHG_ISU_ABBRV4");
        dts_Isu.setCellData(i, "AFCHG_ISU_ENG_ABBRV", /*ORG SRC: dts_Isu.setNameString(i, "AFCHG_ISU_ENG_ABBRV", dts_Isu.NameString(i, "AFCHG_ISU_ENG_ABBRV") = );*/ X = X);
        dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV3") + dts_Isu.getCellData(i, "AFCHG_ISU_ENG_ABBRV4");
    }
    grd_isu.redraw = true;
    return true;
};
scwin.fn_CheckForm = function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_MktactEnforceDd, "변경상장", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_ChgRsnContn, "상호변경사유")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComNm, "변경후한글회사명")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComAbbrv, "한글회사약명")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComEngNm, "영문회사명")) return false;
    if (!$c.stf.checkEmptyValue(txb_AfchgComEngAbbrv, "영문회사약명")) return false;
    if (scwin.gubun == '1') {
        if (!$c.stf.checkEmptyValue(txb_AfchgElwIsurNm, "발행자명")) return false;
        if (!$c.stf.checkEmptyValue(txb_AfchgElwIsurEngNm, "영문발행자명")) return false;
    } else if (scwin.gubun == '2') {
        if (!$c.stf.checkEmptyValue(txb_AfchgUlyNm, "기초자산명")) return false;
        if (!$c.stf.checkEmptyValue(txb_AfchgUlyEngNm, "영문기초자산명")) return false;
    }
    if (!$c.stf.checkMaxLength(txb_ChgRsnContn, 2000, "상호변경사유")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComNm, 80, "변경후한글회사명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComAbbrv, 40, "한글회사약명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComEngNm, 80, "영문회사명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgComEngAbbrv, 40, "영문회사약명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgElwIsurNm, 6, "발행자명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgElwIsurEngNm, 6, "영문발행자명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgUlyNm, 8, "기초자산명")) return false;
    if (!$c.stf.checkMaxLength(txb_AfchgUlyEngNm, 8, "영문기초자산명")) return false;
    if (dts_CheckDate.getTotalRow() > 0) {
        for (var i = 1; i <= dts_CheckDate.getTotalRow(); i++) {
            if ((dts_CheckDate.getCellData(i, "MKTACT_ENFORCE_DD") == $c.stf.getObjectValue(edt_MktactEnforceDd)) && scwin.fr_bz_procs_no == "") {
                $c.win.alert("변경상장일에 해당하는 데이터가 존재합니다.\n변경상장일을 확인해주세요.");
                return false;
            }
        }
    }
    return true;
};
scwin.fn_save_trs = function() {
    if (!scwin.fn_changeIsuNmByBatch()) return;

    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    grd_isu.redraw = false;
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }
    grd_isu.redraw = true;
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lc.fn_encodeNSession("/Listing.do?method=saveChgList&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=2" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_145 + ",DIV_IDX[0]=" + DIV_IDX_CHGLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_CHGLIST_ISU_NM_CHG;
    trs.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    var vTpl = '68953B';
    if (scwin.gubun == "2") {
        vTpl = '68953C';
    }

    //dts_Mst.NameString(dts_Mst.RowPosition,"COM_NM") = Isur_nm;

    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = vTpl;
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 740 + 5;
    var hgt = 790 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.trs_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search();
    }
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_MktactEnforceDd, false);
    }
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
        scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값

    }
    scwin.fn_checkGubun();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    scwin.fn_checkMktactEnforceDd(); //  변경상장일 체크

    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        scwin.fn_search();
    } else {
        scwin.fn_new_onload(); // 신규작성시 호출		

    }
    $c.libRoundPanel.PanelToGroupBox(panel_3);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_MktactEnforceDd_onclick = function() {
    popUpCalendar2(edt_MktactEnforceDd);
};
scwin.btn_isunm_batch_change_onclick = function() {
    scwin.fn_changeIsuNmByBatch();
};
